  versionCompare: function (g, c) {
    g = g || "";
    c = c || "";
    if (g === c) {
      return 0;
    }
    if (typeof g !== "string") {
      g = "";
    }
    if (typeof c !== "string") {
      c = "";
    }
    var h = g.split(".");
    var f = c.split(".");
    var i = Math.min(h.length, f.length);
    for (var d = 0; d < i; d++) {
      var a = parseInt(h[d]);
      var b = parseInt(f[d]);
      if (a > b) {
        return 1;
      } else {
        if (a < b) {
          return -1;
        }
      }
    }
    if (h.length > f.length) {
      return 1;
    } else {
      if (h.length < f.length) {
        return -1;
      }
    }
    return 0;
  },
