CR.TableBrowser.developerSecurityCheck = function (b) {
  b = Ext.apply(
    { callbackFunction: CR.Core.emptyFunction, callbackScope: this },
    b,
  );
  if (typeof CR.TableBrowser.developerSecurityEventSerial === "undefined") {
    CR.TableBrowser.developerSecurityEventSerial = null;
    var a = new CR.XML();
    var i = a.addContainer(a.getRootElement(), "sequence");
    var g = a.addContainer(i, "transaction");
    var d = a.addContainer(g, "step");
    var c = a.addContainer(d, "search");
    a.setAttribute(c, "label", "SECURITY_EVENT_search");
    a.addText(c, "tableName", "SECURITY_EVENT");
    a.addText(c, "filterName", "BY_DESCRIPTION_CUSTOM");
    a.addOption(c, "includeSelectColumns", "Y");
    a.addOption(c, "includeTotalHitCount", "Y");
    a.addCount(c, "returnLimit", "1");
    var h = a.addContainer(c, "parameter");
    a.addText(h, "columnName", "DESCRIPTION");
    a.addText(h, "contents", "Developer");
    CR.Core.ajaxRequest({
      url: "DirectXMLPostJSON",
      xmlData: a.getXMLDocument(),
      success: function (k) {
        var o = null;
        var m = "failed";
        var l = [];
        var j = CR.JSON.parse(k.responseText);
        var n = j.query;
        if (n) {
          Ext.each(n.sequence, function (p) {
            Ext.each(p.transaction, function (q) {
              m = q.$attr.result;
              Ext.each(q.exception, function (r) {
                l.push(r.message);
              });
              Ext.each(q.step, function (r) {
                if (
                  r.tranResult &&
                  r.tranResult.category &&
                  r.tranResult.category.option &&
                  r.tranResult.category.option === "E"
                ) {
                  l.push(r.tranResult.description);
                } else {
                  if (
                    r.search &&
                    r.search.$attr &&
                    r.search.$attr.label === "SECURITY_EVENT_search"
                  ) {
                    o = r.search;
                  }
                }
              });
            });
          });
        }
        if (m !== "posted" || l.length > 0) {
          CR.Core.displayExceptions({ items: l });
        } else {
          if (
            o.resultRow &&
            o.resultRow[0].selectColumn &&
            o.resultRow[0].selectColumn[0].contents === "Developer"
          ) {
            CR.TableBrowser.developerSecurityEventSerial =
              o.resultRow[0].serial;
          }
          CR.TableBrowser.developerSecurityCheck(b);
        }
      },
    });
  } else {
    if (!CR.TableBrowser.developerSecurityEventSerial) {
      b.callbackFunction.call(b.callbackScope, false);
    } else {
      var a = new CR.XML();
      var i = a.addContainer(a.getRootElement(), "sequence");
      var g = a.addContainer(i, "transaction");
      var d = a.addContainer(g, "step");
      var f = a.addContainer(d, "securityCheck");
      a.addOption(f, "operation", "VIEW");
      a.addSerial(
        f,
        "securityEventSerial",
        CR.TableBrowser.developerSecurityEventSerial,
      );
      CR.Core.ajaxRequest({
        url: "DirectXMLPostJSON",
        xmlData: a.getXMLDocument(),
        scope: this,
        success: function (k) {
          var p = null;
          var m = "failed";
          var l = [];
          var j = CR.JSON.parse(k.responseText);
          var o = j.query;
          if (o) {
            Ext.each(o.sequence, function (q) {
              Ext.each(q.transaction, function (r) {
                m = r.$attr.result;
                Ext.each(r.exception, function (s) {
                  l.push(s.message);
                });
                Ext.each(r.step, function (s) {
                  if (
                    s.tranResult &&
                    s.tranResult.category &&
                    s.tranResult.category.option &&
                    s.tranResult.category.option === "E"
                  ) {
                    l.push(s.tranResult.description);
                  } else {
                    if (s.securityCheck) {
                      p = s.securityCheck;
                    }
                  }
                });
              });
            });
          }
          if (m !== "posted" || l.length > 0) {
            CR.Core.displayExceptions({ items: l });
          } else {
            var n = false;
            if (
              p &&
              (!p.accessResult ||
                (p.accessResult && p.accessResult.option !== "D"))
            ) {
              n = true;
            }
            b.callbackFunction.call(b.callbackScope, n);
          }
        },
      });
    }
  }
};
